using System.Collections.Generic;
using UnityEngine;

// Unity migration prototype: systems are functional foundations, not final production art.
public class EclipseStrikersBootstrap : MonoBehaviour
{
    const float PitchLength=30f, PitchWidth=18f, MatchSeconds=300f;
    readonly List<Transform> home=new List<Transform>(), away=new List<Transform>();
    Transform ball, player, cam;
    Vector3 move, joystickOrigin;
    float timeLeft=MatchSeconds, abilityCooldown, sprintEnergy=100f, shotCharge;
    int homeScore, awayScore, selectedCharacter, coins;
    bool started, ended, paused, tutorial=true, settingsOpen, showTasks, sprinting, abilityActive;
    bool soundOn=true, vibrationOn=true;
    string status="Choose PLAY to start your match";
    GUIStyle hud, big, buttonStyle, small;
    readonly string[] characters={"VOLT","SHADOW","NOVA","PHANTOM"};
    readonly Color[] teamColors={new Color(.05f,.32f,1f),new Color(.75f,.05f,.95f),new Color(.05f,.8f,.8f),new Color(.15f,.15f,.2f)};
    Color homeColor=new Color(.05f,.32f,1f), awayColor=new Color(.9f,.06f,.15f);
    int shots, passes, tackles, abilities;
    bool scoredTask;
    void Start(){Application.targetFrameRate=60;coins=PlayerPrefs.GetInt("es_coins",0);selectedCharacter=PlayerPrefs.GetInt("es_character",0);Pitch();Goals();Teams();Ball();CameraSetup();}
    Material MaterialOf(Color c){Shader s=Shader.Find("Universal Render Pipeline/Lit");if(s==null)s=Shader.Find("Standard");var m=new Material(s);m.color=c;return m;}
    GameObject Box(string n,Vector3 p,Vector3 s,Color c){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().material=MaterialOf(c);return g;}
    void Pitch(){Color grass=new Color(.07f,.31f,.15f),white=new Color(.92f,.95f,.9f);Box("Pitch",Vector3.zero,new Vector3(PitchLength,.2f,PitchWidth),grass);Box("Halfway",new Vector3(0,.12f,0),new Vector3(.07f,.025f,PitchWidth),white);Box("Touchline",new Vector3(0,.12f,PitchWidth/2),new Vector3(PitchLength,.025f,.07f),white);Box("Touchline",new Vector3(0,.12f,-PitchWidth/2),new Vector3(PitchLength,.025f,.07f),white);Box("Endline",new Vector3(-PitchLength/2,.12f,0),new Vector3(.07f,.025f,PitchWidth),white);Box("Endline",new Vector3(PitchLength/2,.12f,0),new Vector3(.07f,.025f,WidthSafe()),white);var c=GameObject.CreatePrimitive(PrimitiveType.Cylinder);c.name="Center circle";c.transform.position=new Vector3(0,.13f,0);c.transform.localScale=new Vector3(5,.025f,5);c.GetComponent<Renderer>().material=MaterialOf(white);var inner=GameObject.CreatePrimitive(PrimitiveType.Cylinder);inner.name="Circle fill";inner.transform.position=new Vector3(0,.16f,0);inner.transform.localScale=new Vector3(4.8f,.03f,4.8f);inner.GetComponent<Renderer>().material=MaterialOf(grass);}
    float WidthSafe(){return PitchWidth;}
    void Goals(){foreach(int side in new int[]{-1,1}){float x=side*(PitchLength/2+1);Box("Post",new Vector3(x,.9f,-2),new Vector3(.15f,1.8f,.15f),Color.white);Box("Post",new Vector3(x,.9f,2),new Vector3(.15f,1.8f,.15f),Color.white);Box("Crossbar",new Vector3(x,1.8f,0),new Vector3(.15f,.15f,4.1f),Color.white);Box("Net",new Vector3(x+side*.7f,.9f,0),new Vector3(.08f,1.8f,4),Color.gray);}}
    Transform MakePlayer(string n,Vector3 pos,Color shirt,bool isHome,int index){var root=new GameObject(n).transform;root.position=pos;var body=GameObject.CreatePrimitive(PrimitiveType.Capsule);body.name="Body";body.transform.SetParent(root,false);body.transform.localPosition=new Vector3(0,.9f,0);body.transform.localScale=new Vector3(.62f,.85f,.62f);body.GetComponent<Renderer>().material=MaterialOf(shirt);var head=GameObject.CreatePrimitive(PrimitiveType.Sphere);head.name="Head";head.transform.SetParent(root,false);head.transform.localPosition=new Vector3(0,1.85f,0);head.transform.localScale=Vector3.one*.46f;head.GetComponent<Renderer>().material=MaterialOf(new Color(.94f,.7f,.53f));var marker=root.gameObject.AddComponent<PlayerMarker>();marker.isHome=isHome;marker.index=index;return root;}
    void Teams(){for(int i=0;i<4;i++){float z=(i-1.5f)*3.2f;home.Add(MakePlayer("Eclipse FC "+(i+1),new Vector3(-8+i*2,0,z),homeColor,true,i));away.Add(MakePlayer("Rival FC "+(i+1),new Vector3(7-i*2,0,-z),awayColor,false,i));}player=home[1];}
    void Ball(){var b=GameObject.CreatePrimitive(PrimitiveType.Sphere);b.name="Football";b.transform.position=new Vector3(-1,.5f,0);b.transform.localScale=Vector3.one*.62f;b.GetComponent<Renderer>().material=MaterialOf(Color.white);var rb=b.AddComponent<Rigidbody>();rb.mass=.45f;rb.drag=.45f;rb.angularDrag=.2f;rb.collisionDetectionMode=CollisionDetectionMode.Continuous;ball=b.transform;}
    void CameraSetup(){var c=Camera.main;if(c==null){var g=new GameObject("Main Camera");c=g.AddComponent<Camera>();g.tag="MainCamera";}cam=c.transform;cam.position=new Vector3(0,16,-19);cam.rotation=Quaternion.Euler(38,0,0);c.fieldOfView=62;}
    void Update(){if(!started||ended||paused)return;timeLeft=Mathf.Max(0,timeLeft-Time.deltaTime);abilityCooldown=Mathf.Max(0,abilityCooldown-Time.deltaTime);if(timeLeft<=0){ended=true;status=homeScore>awayScore?"VICTORY!":homeScore<awayScore?"MATCH LOST":"DRAW";if(homeScore>awayScore){coins+=100;PlayerPrefs.SetInt("es_coins",coins);}return;}ReadMove();bool fast=Input.GetKey(KeyCode.LeftShift)||sprinting;float speed=fast&&sprintEnergy>0?7.4f:5.2f;sprintEnergy=Mathf.Clamp(sprintEnergy+(fast?-24f:15f)*Time.deltaTime,0,100);player.position+=move.normalized*speed*Time.deltaTime;player.position=new Vector3(Mathf.Clamp(player.position.x,-14,14),0,Mathf.Clamp(player.position.z,-8,8));if(move.sqrMagnitude>.05f)player.rotation=Quaternion.Slerp(player.rotation,Quaternion.LookRotation(move),Time.deltaTime*10);if(Input.GetKeyDown(KeyCode.Space))Shoot();if(Input.GetKeyDown(KeyCode.E))Pass();if(Input.GetKeyDown(KeyCode.Q))Ability();if(Input.GetKeyDown(KeyCode.F))Tackle();if(Input.GetKeyDown(KeyCode.Tab))SwitchPlayer();foreach(var p in away)Chase(p,ball.position,2.5f);foreach(var p in home)if(p!=player)Chase(p,ball.position+new Vector3(-1,0,Mathf.Sin(Time.time+p.position.z)),1.6f);cam.position=Vector3.Lerp(cam.position,player.position+new Vector3(0,14,-17),Time.deltaTime*3);cam.LookAt(player.position+Vector3.up*.5f);CheckGoal();}
    void ReadMove(){move=Vector3.zero;if(Input.GetKey(KeyCode.W)||Input.GetKey(KeyCode.UpArrow))move.z++;if(Input.GetKey(KeyCode.S)||Input.GetKey(KeyCode.DownArrow))move.z--;if(Input.GetKey(KeyCode.A)||Input.GetKey(KeyCode.LeftArrow))move.x--;if(Input.GetKey(KeyCode.D)||Input.GetKey(KeyCode.RightArrow))move.x++;if(Input.touchCount>0){Touch t=Input.GetTouch(0);if(t.position.x<Screen.width*.48f){Vector2 d=(t.position-new Vector2(Screen.width*.2f,Screen.height*.78f))/Mathf.Max(80,Screen.width*.16f);move=new Vector3(Mathf.Clamp(d.x,-1,1),0,Mathf.Clamp(d.y,-1,1));}}}
    void Chase(Transform p,Vector3 target,float speed){target.y=0;Vector3 d=target-p.position;if(d.magnitude>1.4f)p.position+=d.normalized*speed*Time.deltaTime;}
    bool NearBall(float distance=3f){return Vector3.Distance(player.position,ball.position)<=distance;}
    void Shoot(){if(!NearBall()) {status="Move closer to the ball";return;}Vector3 d=(Vector3.right+player.forward*.35f+Vector3.up*.24f).normalized;ball.GetComponent<Rigidbody>().AddForce(d*14f,ForceMode.Impulse);shots++;status="POWER SHOT!";player.localScale=new Vector3(1.12f,1,1);Invoke("ResetPlayerScale",.22f);}
    void ResetPlayerScale(){if(player!=null)player.localScale=Vector3.one;}
    void Pass(){if(!NearBall())return;Transform mate=null;float best=999;foreach(var p in home){if(p==player)continue;float d=Vector3.Distance(player.position,p.position);if(d<best){best=d;mate=p;}}if(mate==null)return;Vector3 dir=(mate.position-ball.position+Vector3.up*.15f).normalized;ball.GetComponent<Rigidbody>().AddForce(dir*7.5f,ForceMode.Impulse);passes++;status="PASS!";}
    void Ability(){if(abilityCooldown>0){status="Ability recharging";return;}abilityCooldown=7f;abilities++;player.position+=player.forward*3.5f;player.localScale=new Vector3(1.25f,1,1.25f);Invoke("ResetPlayerScale",.35f);status=characters[Mathf.Clamp(selectedCharacter,0,characters.Length-1)]+" SPECIAL BURST!";}
    void Tackle(){Transform target=null;float best=2.8f;foreach(var p in away){float d=Vector3.Distance(player.position,p.position);if(d<best){best=d;target=p;}}if(target!=null){target.position+=(-player.forward)*2f;var rb=ball.GetComponent<Rigidbody>();rb.AddForce(player.forward*4f,ForceMode.Impulse);tackles++;status="TACKLE!";}else status="No opponent in range";}
    void SwitchPlayer(){int i=home.IndexOf(player);player=home[(i+1)%home.Count];status="Player switched";}
    void CheckGoal(){if(Mathf.Abs(ball.position.x)<PitchLength/2-1||Mathf.Abs(ball.position.z)>2.2f||ball.position.y>3)return;if(ball.position.x>0)homeScore++;else awayScore++;scoredTask=true;status="GOAL!";ball.position=new Vector3(0,.5f,0);var rb=ball.GetComponent<Rigidbody>();rb.velocity=Vector3.zero;rb.angularVelocity=Vector3.zero;for(int i=0;i<4;i++){float z=(i-1.5f)*3.2f;home[i].position=new Vector3(-8+i*2,0,z);away[i].position=new Vector3(7-i*2,0,-z);}}
    void StartMatch(){started=true;paused=false;ended=false;timeLeft=MatchSeconds;homeScore=awayScore=shots=passes=tackles=abilities=0;scoredTask=false;tutorial=PlayerPrefs.GetInt("es_tutorial_done",0)==0;status="Match started!";if(tutorial)PlayerPrefs.SetInt("es_tutorial_done",1);}
    void OnGUI(){if(hud==null){hud=new GUIStyle(GUI.skin.label);hud.fontSize=Mathf.Max(17,Screen.height/40);hud.normal.textColor=Color.white;big=new GUIStyle(GUI.skin.label);big.fontSize=Mathf.Max(25,Screen.height/24);big.fontStyle=FontStyle.Bold;big.normal.textColor=Color.white;buttonStyle=new GUIStyle(GUI.skin.button);buttonStyle.fontSize=Mathf.Max(16,Screen.height/55);small=new GUIStyle(GUI.skin.label);small.fontSize=Mathf.Max(12,Screen.height/65);small.normal.textColor=Color.white;}
        if(!started){GUI.Box(new Rect(0,0,Screen.width,Screen.height),"");GUI.Label(new Rect(20,Screen.height*.12f,Screen.width-40,55),"ECLIPSE STRIKERS",big);GUI.Label(new Rect(22,Screen.height*.23f,Screen.width-44,45),"ANIME FOOTBALL • OFFLINE 4v4",hud);GUI.Label(new Rect(22,Screen.height*.32f,Screen.width-44,35),"CHOOSE YOUR STRIKER",hud);for(int i=0;i<characters.Length;i++){int ix=i;if(GUI.Button(new Rect(20+i*(Screen.width-40)/4,Screen.height*.39f,(Screen.width-50)/4,55),characters[i]+(selectedCharacter==i?" ✓":""))) {selectedCharacter=ix;PlayerPrefs.SetInt("es_character",ix);homeColor=teamColors[ix];RefreshTeamColors();}}if(GUI.Button(new Rect(Screen.width*.15f,Screen.height*.55f,Screen.width*.7f,70),"PLAY 4v4 MATCH"))StartMatch();if(GUI.Button(new Rect(20,Screen.height*.68f,Screen.width*.42f,55),"TASKS / COINS"))showTasks=!showTasks;if(GUI.Button(new Rect(Screen.width*.54f,Screen.height*.68f,Screen.width*.42f,55),"SETTINGS"))settingsOpen=!settingsOpen;GUI.Label(new Rect(20,Screen.height*.82f,Screen.width-40,60),"Coins: "+coins+"  •  Unity migration prototype",small);if(showTasks)DrawTasks();if(settingsOpen)DrawSettings();return;}
        GUI.Box(new Rect(10,10,Screen.width-20,58),"");int sec=Mathf.CeilToInt(timeLeft);GUI.Label(new Rect(20,14,Screen.width-40,48),"ECLIPSE STRIKERS    "+homeScore+" - "+awayScore+"    "+(sec/60)+":"+((sec%60).ToString("00")),hud);GUI.Label(new Rect(16,70,Screen.width-32,32),status,small);GUI.Label(new Rect(16,98,Screen.width-32,28),"SPRINT "+Mathf.RoundToInt(sprintEnergy)+"%   ABILITY "+(abilityCooldown<=0?"READY":abilityCooldown.ToString("0.0")+"s"),small);
        if(GUI.Button(new Rect(12,Screen.height-100,90,72),sprinting?"SPRINT ON":"SPRINT"))sprinting=!sprinting;
        if(GUI.Button(new Rect(Screen.width-112,Screen.height-98,100,70),"SHOOT"))Shoot();
        if(GUI.Button(new Rect(Screen.width-222,Screen.height-98,100,70),"PASS"))Pass();
        if(GUI.Button(new Rect(Screen.width-112,Screen.height-178,100,66),"SPECIAL"))Ability();
        if(GUI.Button(new Rect(Screen.width-222,Screen.height-178,100,66),"TACKLE"))Tackle();
        if(GUI.Button(new Rect(12,Screen.height-178,90,66),"SWITCH"))SwitchPlayer();
        if(GUI.Button(new Rect(Screen.width-90,70,78,42),paused?"RESUME":"PAUSE"))paused=!paused;
        if(tutorial)GUI.Box(new Rect(Screen.width*.12f,Screen.height*.22f,Screen.width*.76f,100),"Tutorial: drag left side to move. Use SHOOT, PASS, TACKLE and SPECIAL on the right.");
        if(paused){GUI.Box(new Rect(Screen.width*.2f,Screen.height*.3f,Screen.width*.6f,Screen.height*.38f),"PAUSED");if(GUI.Button(new Rect(Screen.width*.28f,Screen.height*.4f,Screen.width*.44f,55),"RESUME"))paused=false;if(GUI.Button(new Rect(Screen.width*.28f,Screen.height*.51f,Screen.width*.44f,55),"MAIN MENU")){started=false;paused=false;}}
        if(ended){GUI.Box(new Rect(Screen.width*.15f,Screen.height*.32f,Screen.width*.7f,Screen.height*.3f),status+"\n"+homeScore+" - "+awayScore);if(GUI.Button(new Rect(Screen.width*.2f,Screen.height*.5f,Screen.width*.28f,55),"REMATCH"))StartMatch();if(GUI.Button(new Rect(Screen.width*.52f,Screen.height*.5f,Screen.width*.28f,55),"MENU"))started=false;}
    }
    void RefreshTeamColors(){for(int i=0;i<home.Count;i++){var r=home[i].Find("Body").GetComponent<Renderer>();r.material=MaterialOf(homeColor);}}
    void DrawTasks(){GUI.Box(new Rect(20,Screen.height*.25f,Screen.width-40,Screen.height*.48f),"DAILY TASKS");GUI.Label(new Rect(35,Screen.height*.31f,Screen.width-70,35),"Complete a match: +50 coins",hud);if(GUI.Button(new Rect(35,Screen.height*.38f,Screen.width-70,50),"CLAIM MATCH REWARD")&&PlayerPrefs.GetInt("es_match_reward",0)==0){coins+=50;PlayerPrefs.SetInt("es_match_reward",1);PlayerPrefs.SetInt("es_coins",coins);}GUI.Label(new Rect(35,Screen.height*.48f,Screen.width-70,35),"Passes: "+passes+"   Tackles: "+tackles+"   Abilities: "+abilities,small);if(GUI.Button(new Rect(35,Screen.height*.58f,Screen.width-70,48),"CLOSE"))showTasks=false;}
    void DrawSettings(){GUI.Box(new Rect(20,Screen.height*.25f,Screen.width-40,Screen.height*.45f),"SETTINGS");if(GUI.Button(new Rect(35,Screen.height*.34f,Screen.width-70,50),"Sound: "+(soundOn?"ON":"OFF")))soundOn=!soundOn;if(GUI.Button(new Rect(35,Screen.height*.43f,Screen.width-70,50),"Vibration: "+(vibrationOn?"ON":"OFF")))vibrationOn=!vibrationOn;if(GUI.Button(new Rect(35,Screen.height*.54f,Screen.width-70,50),"CLOSE"))settingsOpen=false;}
}
public class PlayerMarker:MonoBehaviour{public bool isHome;public int index;}
